void log_msg(const char *s) {
    xSemaphoreTake(uart_mtx, portMAX_DELAY);
    uart_write(s);
    xSemaphoreGive(uart_mtx);
}

void sensor_task(void *p) {          // every 10 ms
    for (;;) {
        xSemaphoreTake(i2c_mtx, portMAX_DELAY);
        read_sensor();
        log_msg("read ok");           // still holding i2c_mtx
        xSemaphoreGive(i2c_mtx);
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

void console_task(void *p) {         // on a UART command
    xSemaphoreTake(uart_mtx, portMAX_DELAY);
    print_sensor_status();           // takes i2c_mtx inside
    xSemaphoreGive(uart_mtx);
}
